macro.command:
if(args[0].macroPass === "templatePlaced") {
    if(!game.modules.get("effectmacro")?.active) return;
    async function wait(ms) { return new Promise(resolve => { setTimeout(resolve, ms); }); }
    const targetsSet = workflow.targets;
    const targetsArray = Array.from(targetsSet);
    const excludedTypes = ["undead", "construct"];
    const actorProf = actor.system.attributes.prof;

    const validTargetsArray = targetsArray.filter(target => {
        const creatureType = MidiQOL.raceOrType(target);
        return !excludedTypes.includes(creatureType);
    });

    for (const validTarget of validTargetsArray) {
    const effectId = foundry.utils.randomID();
    const tempEffectData = [{
        _id: effectId,
        img: macroItem.img,
        "name": macroItem.name,
        "origin": macroItem.uuid,
        "disabled": false,
        "duration": { value: 1, units: "rounds" },
        "flags": {
            "effectmacro": {
                "onCreate": {
                    "script": `
                        const validTarget = await fromUuid(${JSON.stringify(validTarget.document.uuid)});

                        let effectBlinded = validTarget.actor.appliedEffects.find(e => e.statuses.has("blinded"));
                        let effectDeafened = validTarget.actor.appliedEffects.find(e => e.statuses.has("deafened"));
                        let effectParalyzed = validTarget.actor.appliedEffects.find(e => e.statuses.has("paralyzed"));
                        let effectPoisoned = validTarget.actor.appliedEffects.find(e => e.statuses.has("poisoned"));

                        let buttons = [
                            {
                                action: "Healing",
                                label: game.i18n.localize("GAMBITSPREMADES.Dialogs.HealingGlyph.Healing"),
                                callback: async () => {
                                    const targetMaxHp = validTarget.actor.system.attributes.hp.max;
                                    const targetCurrentHp = validTarget.actor.system.attributes.hp.value;
                                    let healRoll = await new CONFIG.Dice.DamageRoll("3d8 + ${actorProf}", {}, {type: "healing", properties: ["mgc"]}).evaluate();
                                    await MidiQOL.displayDSNForRoll(healRoll, 'damageRoll')
                                    let healTotal = healRoll.total;

                                    const itemData = {
                                        name: "Healing Glyph",
                                        type: "feat",
                                        img: ${JSON.stringify(macroItem.img)}
                                    }
                                    await new MidiQOL.DamageOnlyWorkflow(validTarget.actor, validTarget.object, healRoll.total, "healing", validTarget.object ? [validTarget.object] : [], healRoll, {itemData: itemData, flavor: "Healing Glyph"});
                                    if(game.gps.getCprConfig({itemUuid: ${JSON.stringify(macroItem.uuid)}}).animEnabled) {
                                        new Sequence()

                                        .effect()
                                        .file("jb2a.particle_burst.01.circle.green")
                                        .attachTo(validTarget.object)
                                        .scaleToObject(3)
                                        .opacity(1)
                                        .zIndex(0)
                                        .belowTokens(false)
                                        .fadeIn(1500)
                                        .fadeOut(1500)

                                        .play()
                                    }

                                    let displayHp = healTotal;
                                    if((healTotal + targetCurrentHp) > targetMaxHp) displayHp = targetMaxHp - targetCurrentHp;

                                    let content = game.i18n.format("GAMBITSPREMADES.ChatMessages.HealingGlyph.Healed", {hitPoints: displayHp});
                                    let actorPlayer = MidiQOL.playerForActor(validTarget.actor);
                                    let chatData = {
                                    user: actorPlayer?.id ?? game.user.id,
                                    speaker: ChatMessage.getSpeaker({ token: validTarget }),
                                    content: content
                                    };
                                    ChatMessage.create(chatData);
                                }
                            }
                        ];

                        // Dynamically add buttons based on conditions
                        if (effectBlinded) {
                            buttons.push({
                                action: "Restoration - Blinded",
                                label: game.i18n.format("GAMBITSPREMADES.Dialogs.HealingGlyph.Restoration", {condition: game.i18n.localize("DND5E.ConBlinded")}),
                                callback: async () => {
                                    await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: validTarget.actor.uuid, effects: [effectBlinded.id] });
                                    const content = game.i18n.format("GAMBITSPREMADES.ChatMessages.HealingGlyph.Restored", {condition: game.i18n.localize("DND5E.ConBlinded")});
                                    let actorPlayer = MidiQOL.playerForActor(validTarget.actor);
                                    let chatData = {
                                    user: actorPlayer?.id ?? game.user.id,
                                    speaker: ChatMessage.getSpeaker({ token: validTarget }),
                                    content: content
                                    };
                                    ChatMessage.create(chatData);
                                }
                            });
                        }

                        if (effectDeafened) {
                            buttons.push({
                                action: "Restoration - Deafened",
                                label: game.i18n.format("GAMBITSPREMADES.Dialogs.HealingGlyph.Restoration", {condition: game.i18n.localize("DND5E.ConDeafened")}),
                                callback: async () => {
                                    await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: validTarget.actor.uuid, effects: [effectDeafened.id] });
                                    const content = game.i18n.format("GAMBITSPREMADES.ChatMessages.HealingGlyph.Restored", {condition: game.i18n.localize("DND5E.ConDeafened")});
                                    let actorPlayer = MidiQOL.playerForActor(validTarget.actor);
                                    let chatData = {
                                    user: actorPlayer?.id ?? game.user.id,
                                    speaker: ChatMessage.getSpeaker({ token: validTarget }),
                                    content: content
                                    };
                                    ChatMessage.create(chatData);
                                }
                            });
                        }

                        if (effectParalyzed) {
                            buttons.push({
                                action: "Restoration - Paralyzed",
                                label: game.i18n.format("GAMBITSPREMADES.Dialogs.HealingGlyph.Restoration", {condition: game.i18n.localize("DND5E.ConParalyzed")}),
                                callback: async () => {
                                    await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: validTarget.actor.uuid, effects: [effectParalyzed.id] });
                                    const content = game.i18n.format("GAMBITSPREMADES.ChatMessages.HealingGlyph.Restored", {condition: game.i18n.localize("DND5E.ConParalyzed")});
                                    let actorPlayer = MidiQOL.playerForActor(validTarget.actor);
                                    let chatData = {
                                    user: actorPlayer?.id ?? game.user.id,
                                    speaker: ChatMessage.getSpeaker({ token: validTarget }),
                                    content: content
                                    };
                                    ChatMessage.create(chatData);
                                }
                            });
                        }

                        if (effectPoisoned) {
                            buttons.push({
                                action: "Restoration - Poisoned",
                                label: game.i18n.format("GAMBITSPREMADES.Dialogs.HealingGlyph.Restoration", {condition: game.i18n.localize("DND5E.ConPoisoned")}),
                                callback: async () => {
                                    await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: validTarget.actor.uuid, effects: [effectPoisoned.id] });
                                    const content = game.i18n.format("GAMBITSPREMADES.ChatMessages.HealingGlyph.Restored", {condition: game.i18n.localize("DND5E.ConPoisoned")});
                                    let actorPlayer = MidiQOL.playerForActor(validTarget.actor);
                                    let chatData = {
                                    user: actorPlayer?.id ?? game.user.id,
                                    speaker: ChatMessage.getSpeaker({ token: validTarget }),
                                    content: content
                                    };
                                    ChatMessage.create(chatData);
                                }
                            });
                        }
                        await game.gps.showAutomationDialog({
                            window: { title: ${JSON.stringify(validTarget.actor.name + " | Healing Glyph")} },
                            content: \`
                                <div class='gps-dialog-container'>
                                    <div class='gps-dialog-section'>
                                        <div class='gps-dialog-content'>
                                            <div>
                                                <div class='gps-dialog-flex'>
                                                    <p class='gps-dialog-paragraph'>${game.i18n.localize("GAMBITSPREMADES.Dialogs.HealingGlyph.Prompt")}</p>
                                                    <div id='image-container' class='gps-dialog-image-container'>
                                                        <img src='${macroItem.img}' class='gps-dialog-image'>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            \`,
                            buttons: buttons,
                            default: "healing"
                        });
                    `
                }
            }
        }
    }];

    await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: validTarget.actor.uuid, effects: tempEffectData, options: {keepId: true} });
    await wait(100);
    if(validTarget.actor.effects.has(effectId)) await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: validTarget.actor.uuid, effects: [effectId] });
    }
}
